"use client";

import { useParams, useRouter } from "next/navigation";
import { useState } from "react";
import phones from "@/data/phones.json";
import minerals from "@/data/minerals.json";

const SVG_WIDTH = 2150;
const SVG_HEIGHT = 1600;

type DiagramComponent = {
  id: string;
  label: string;
  mineral: string;
  description: string;
  labelPos: { x: number; y: number };
  highlightPath: string;
};

const COMPONENTS: DiagramComponent[] = [
  {
    id: "front-camera",
    label: "Front Camera",
    mineral: "rare-earths",
    description:
      "7 MP TrueDepth camera. Rare earth elements coat the lens and power the image sensor.",
    labelPos: { x: 1015, y: 566 },
    highlightPath:
      "M204 620 L286 580 L332 612 L300 686 L224 706 L187 670 Z",
  },
  {
    id: "rear-camera",
    label: "Rear Cameras",
    mineral: "rare-earths",
    description:
      "48 MP Fusion camera system. Rare earth optical coatings and magnetic lens actuators.",
    labelPos: { x: 322, y: 637 },
    highlightPath:
      "M148 752 L230 686 L440 780 L314 935 L138 854 Z",
  },
  {
    id: "circuit-board",
    label: "Circuit Board",
    mineral: "tin",
    description:
      "Main PCB. Tin solder holds every chip, capacitor, and connector in place.",
    labelPos: { x: 654, y: 790 },
    highlightPath:
      "M512 728 L1042 842 L892 1020 L474 930 L398 856 Z",
  },
  {
    id: "processor",
    label: "Processor",
    mineral: "rare-earths",
    description:
      "Apple A18 Bionic. Rare earth elements in the package substrate and on-chip magnets.",
    labelPos: { x: 1023, y: 818 },
    highlightPath:
      "M592 666 L708 692 L656 776 L540 748 Z",
  },
  {
    id: "battery",
    label: "Battery",
    mineral: "cobalt",
    description:
      "3,561 mAh lithium-ion cell. Contains ~10 g of cobalt, most of it mined in the DRC.",
    labelPos: { x: 763, y: 942 },
    highlightPath:
      "M344 876 L628 1020 L544 1132 L312 1002 L244 926 Z",
  },
  {
    id: "display",
    label: "Display",
    mineral: "rare-earths",
    description:
      "6.1\" Super Retina XDR OLED. Indium tin oxide touch layer, rare earth phosphors.",
    labelPos: { x: 1004, y: 1109 },
    highlightPath:
      "M122 1200 L604 1418 L853 1558 L1058 1410 L1144 1454 L973 1588 L558 1600 L182 1466 L93 1332 Z",
  },
];

const MINERAL_COLORS: Record<string, string> = {
  cobalt: "#3B5BDB",
  tantalum: "#862E9C",
  tungsten: "#495057",
  gold: "#F08C00",
  tin: "#74C0FC",
  "rare-earths": "#2F9E44",
};

function toPercentX(value: number) {
  return `${(value / SVG_WIDTH) * 100}%`;
}

function toPercentY(value: number) {
  return `${(value / SVG_HEIGHT) * 100}%`;
}

export default function DiagramPage() {
  const { phone } = useParams<{ phone: string }>();
  const router = useRouter();
  const [hovered, setHovered] = useState<string | null>(null);
  const [selected, setSelected] = useState<DiagramComponent | null>(null);

  const phoneData = phones.find((p) => p.id === phone);

  if (!phoneData || phoneData.status !== "active") {
    return (
      <main
        className="flex h-screen w-full items-center justify-center"
        style={{ background: "var(--cream)" }}
      >
        <p style={{ color: "var(--warm-gray)" }}>Phone not found or coming soon.</p>
      </main>
    );
  }

  const activeId = hovered ?? selected?.id ?? null;
  const activeComponent = activeId
    ? COMPONENTS.find((component) => component.id === activeId) ?? null
    : null;
  const mineral = selected ? minerals.find((m) => m.id === selected.mineral) : null;

  function navigateToGlobe(mineralId: string) {
    router.push(`/globe/${mineralId}`);
  }

  return (
    <main
      className="relative flex h-screen w-full flex-col overflow-hidden lg:flex-row"
      style={{ background: "var(--cream)" }}
    >
      <button
        onClick={() => router.push("/select")}
        className="absolute left-5 top-5 z-20 text-xs uppercase tracking-widest sm:left-6 sm:top-6"
        style={{ color: "var(--warm-gray)" }}
      >
        ← Devices
      </button>

      <div className="absolute left-1/2 top-5 z-20 -translate-x-1/2 text-center sm:top-6">
        <p
          className="text-xs uppercase tracking-[0.3em]"
          style={{ color: "var(--warm-gray)" }}
        >
          {phoneData.brand}
        </p>
        <h1 className="text-lg" style={{ color: "var(--ink)" }}>
          {phoneData.name}
        </h1>
      </div>

      <section className="flex min-h-0 flex-1 items-center justify-center px-4 pb-6 pt-24 sm:px-8 lg:px-10 lg:pb-10 lg:pt-20">
        <div className="relative w-full max-w-[1120px]">
          <div className="relative mx-auto aspect-[2150/1600] w-full max-w-[980px]">
            <img
              src="/illustrations/components.svg"
              alt="iPhone 16 component diagram"
              className="h-full w-full select-none object-contain"
              draggable={false}
            />

            <svg
              viewBox={`0 0 ${SVG_WIDTH} ${SVG_HEIGHT}`}
              className="pointer-events-none absolute inset-0 h-full w-full"
              aria-hidden="true"
            >
              {activeComponent ? (
                <path
                  d={activeComponent.highlightPath}
                  fill="rgba(139, 38, 53, 0.18)"
                  stroke="rgba(139, 38, 53, 0.88)"
                  strokeWidth="9"
                  strokeLinejoin="round"
                />
              ) : null}
            </svg>

            {COMPONENTS.map((component) => {
              const isActive = activeId === component.id;

              return (
                <button
                  key={component.id}
                  type="button"
                  onClick={() =>
                    setSelected(selected?.id === component.id ? null : component)
                  }
                  onMouseEnter={() => setHovered(component.id)}
                  onMouseLeave={() => setHovered(null)}
                  onFocus={() => setHovered(component.id)}
                  onBlur={() => setHovered(null)}
                  className="absolute z-10 text-left"
                  style={{
                    left: toPercentX(component.labelPos.x),
                    top: toPercentY(component.labelPos.y),
                    transform: "translateY(-50%)",
                    padding: "3px 8px",
                    background: isActive ? "rgba(139, 38, 53, 0.08)" : "transparent",
                    border: "none",
                    outline: "none",
                    cursor: "pointer",
                  }}
                >
                  <span
                    className="block whitespace-nowrap text-[10px] uppercase tracking-[0.28em] sm:text-xs"
                    style={{
                      color: isActive ? "var(--cranberry)" : "var(--ink)",
                      transition: "color 0.15s ease",
                      fontFamily: "Georgia, 'Times New Roman', serif",
                    }}
                  >
                    {component.label}
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      </section>

      <aside
        className="flex w-full shrink-0 flex-col justify-center border-t px-6 py-8 lg:w-80 lg:border-l lg:border-t-0 lg:px-8 lg:py-12"
        style={{ borderColor: "rgba(176,170,166,0.3)" }}
      >
        {selected && mineral ? (
          <div className="fade-up" key={selected.id}>
            <div
              className="mb-2 text-xs uppercase tracking-[0.25em]"
              style={{ color: MINERAL_COLORS[selected.mineral] }}
            >
              {mineral.name} · {mineral.formula}
            </div>
            <h2 className="mb-3 text-xl" style={{ color: "var(--ink)" }}>
              {selected.label}
            </h2>
            <p
              className="mb-6 text-sm leading-relaxed"
              style={{ color: "var(--warm-gray)" }}
            >
              {selected.description}
            </p>
            <div
              className="mb-4 pb-4 text-xs"
              style={{
                borderBottom: "1px solid rgba(176,170,166,0.3)",
                color: "var(--warm-gray)",
              }}
            >
              Mined in{" "}
              <span style={{ color: "var(--ink)" }}>{mineral.mineLocation.country}</span>
            </div>
            <button
              onClick={() => navigateToGlobe(selected.mineral)}
              className="w-full rounded-[2px] py-2 text-xs uppercase tracking-[0.2em] transition-opacity hover:opacity-80"
              style={{
                background: "var(--cranberry)",
                color: "var(--cream)",
              }}
            >
              Trace the supply chain →
            </button>
            <button
              onClick={() => setSelected(null)}
              className="mt-3 w-full py-1 text-xs uppercase tracking-widest"
              style={{ color: "var(--warm-gray)" }}
            >
              ← Back
            </button>
          </div>
        ) : (
          <p className="text-xs uppercase tracking-[0.25em]" style={{ color: "var(--warm-gray)" }}>
            Hover a label to locate the component. Tap to explore its supply chain.
          </p>
        )}
      </aside>
    </main>
  );
}
